/* ===== Domain 5: Monitor and maintain ===== */
GROUPS.push(
 {id:"m1",domain:"monitor",name:"Monitor resources by using Azure Monitor",lessons:["metrics","diag","kql","alerts","insights"]},
 {id:"m2",domain:"monitor",name:"Implement backup and recovery",lessons:["vaults","bpolicy","restore","asr","breports"]}
);
DOMAINS.find(d=>d.id==="monitor").built=true;

LESSONS.metrics={id:"metrics",title:"Metrics vs logs",mins:2,
 keywords:["azure monitor","metrics","logs","metrics explorer","activity log","platform metrics","retention","93 days","aggregation","log analytics"],
 scenes:[
  {say:"Azure Monitor collects two kinds of data: metrics and logs. Almost every monitoring question starts with knowing which one you need.",
   ops:[B("res","cube",60,220,"vm-web1","Azure resource"),B("am","watcher",380,220,"Azure Monitor","",200),B("me","app",720,110,"Metrics","numbers over time",200),B("lg","app",720,330,"Logs","records you query",200),
        L("l1","res","am"),L("l2","am","me"),L("l3","am","lg"),P(["res","am","me"],"CPU 72%","signal"),P(["res","am","lg"],"event","signal")]},
  {say:"Metrics are lightweight numbers sampled every minute, like CPU percentage. Platform metrics are collected automatically and kept for 93 days.",
   ops:[C(),T("cmp",60,60,[["","Metrics","Logs"],["Data","Numeric time series","Records with many fields"],["Collected","Automatically (platform)","After you configure it"],["Retention","93 days","Workspace setting (30 days default)"],["Explore with","Metrics Explorer","Log Analytics (KQL)"],["Best for","Near real-time alerts, charts","Investigation, correlation"]],"Metrics vs logs"),R("cmp",3,"accent")]},
  {say:"Metrics Explorer charts them. Pick a resource, a metric and an aggregation like average or maximum, then split by a dimension or pin the chart to a dashboard.",
   ops:[R("cmp",4,"accent"),N("n1",60,300,"Aggregations: Avg · Min · Max · Sum · Count\nSplit by dimension · pin to dashboard","accent")]},
  {say:"Logs hold detailed records. They live in a Log Analytics workspace, and you query them with Kusto Query Language.",
   ops:[R("cmp",5,"accent"),...D("n1"),N("n2",60,300,"Logs → Log Analytics workspace → KQL","accent")]},
  {say:"The activity log is special. It records control-plane events, like who created or deleted a resource, for every subscription. It's kept for 90 days.",
   ops:[...D("n2"),T("al",60,300,[["Activity log (subscription)",""],["Operation","Delete Virtual Machine"],["Caller","priya@contoso.com"],["Status","Succeeded"],["Kept","90 days (export for longer)"]])]},
  {say:"Exam pattern: who deleted the VM, activity log. How busy is the CPU, metrics. Why did the app throw errors, logs.",
   ops:[N("n3",520,320,"Who did it? → Activity log\nHow much / how fast? → Metrics\nWhat exactly happened? → Logs","ok")]}
 ],
 takeaways:["Metrics: numeric, 1-minute samples, collected automatically, 93 days retention.","Logs: detailed records in a Log Analytics workspace, queried with KQL.","Metrics Explorer: aggregation, splitting by dimension, pinning to dashboards.","Activity log: subscription control-plane events (who/what/when), kept 90 days."],
 traps:["Resource logs (like storage read requests) aren't collected until you add a diagnostic setting.","Guest OS counters (like memory inside the VM) need an agent; they aren't platform metrics."],
 mnemonic:"Metrics measure, logs explain, the activity log names names.",
 lab:"Open Metrics Explorer on a VM, chart Percentage CPU with Max aggregation over 24 hours, then open the subscription's activity log and filter to Delete operations.",
 ref:"https://learn.microsoft.com/en-us/azure/azure-monitor/fundamentals/overview"};

LESSONS.diag={id:"diag",title:"Diagnostic settings & workspaces",mins:2,
 keywords:["diagnostic settings","resource logs","log analytics workspace","event hub","archive to storage","activity log export","retention","workspace"],
 scenes:[
  {say:"Resource logs, like Key Vault access or storage reads, aren't collected by default. You turn them on with a diagnostic setting on each resource.",
   ops:[B("kv","key",60,220,"kv-prod","Key Vault"),B("ds","policy",380,220,"Diagnostic setting","AuditEvent logs",220)]},
  {say:"A diagnostic setting sends data to up to three kinds of destination: a Log Analytics workspace, a storage account, or an event hub.",
   ops:[B("law","app",720,70,"Log Analytics","query + alert",200),B("st","storage",720,220,"Storage account","cheap archive",200),B("eh","app",720,370,"Event hub","stream to SIEM",200),
        L("a","kv","ds"),L("b","ds","law","","ok"),L("c","ds","st","","ok"),L("d","ds","eh","","ok"),P(["kv","ds","law"],"","signal"),P(["kv","ds","st"],"","signal"),P(["kv","ds","eh"],"","signal")]},
  {say:"Pick by purpose: query and alert in Log Analytics, keep cheaply for years in storage, or stream to an external tool through an event hub.",
   ops:[N("n1",60,330,"Analyze → workspace\nArchive → storage\nStream → event hub","ok")]},
  {say:"The activity log uses a diagnostic setting too, at the subscription level, to keep events longer than 90 days or to query them with KQL.",
   ops:[...D("n1"),N("n2",60,330,"Subscription → Activity log →\nDiagnostic settings → workspace","accent")]},
  {say:"Log Analytics workspaces set retention, 30 days by default, extendable for years. One workspace can collect from many resources and subscriptions.",
   ops:[...D("n2"),N("n3",60,330,"Workspace retention: 30 days default\nOne workspace, many resources","accent")]}
 ],
 takeaways:["Resource logs need a diagnostic setting per resource.","Destinations: Log Analytics workspace, storage account, event hub (and partner solutions).","Activity log export also uses a subscription-level diagnostic setting.","Workspaces default to 30 days of retention; longer is configurable."],
 traps:["\"Query Key Vault access events with KQL\" means a diagnostic setting to a Log Analytics workspace, not to storage.","Streaming logs to a third-party SIEM uses an event hub."],
 mnemonic:"Query, Keep, or Stream: workspace, storage, event hub.",
 lab:"Add a diagnostic setting on a Key Vault sending AuditEvent to a Log Analytics workspace, read a secret, and find the event with AzureDiagnostics in Logs.",
 ref:"https://learn.microsoft.com/en-us/azure/azure-monitor/platform/diagnostic-settings"};

LESSONS.kql={id:"kql",title:"KQL basics",mins:3,
 keywords:["kql","kusto","query","where","summarize","project","render","ago","bin","count","heartbeat","perf","log query"],
 scenes:[
  {say:"KQL queries start with a table, then pipe the rows through operators, one per line, like a production line.",
   ops:[T("q1",60,60,[["Perf"],["| where TimeGenerated > ago(1h)"],["| where CounterName == \"% Processor Time\""],["| summarize avg(CounterValue) by Computer"],["| order by avg_CounterValue desc"]],"Query")]},
  {say:"Where filters rows. Ago gives a relative time, so ago one hour means the last hour.",
   ops:[R("q1",1,"accent")]},
  {say:"Summarize groups and aggregates, like count, average or max, by one or more columns.",
   ops:[R("q1",3,"accent"),T("res",560,60,[["Computer","avg_CounterValue"],["vm-web1","71.4"],["vm-web2","38.2"],["vm-db1","12.9"]],"Result")]},
  {say:"Here are the operators you'll see most.",
   ops:[C(),T("op",60,60,[["Operator","Does"],["where","Filter rows"],["project","Choose or rename columns"],["summarize … by","Aggregate by group"],["bin(TimeGenerated, 5m)","Bucket time"],["order by / top 10 by","Sort or take the top rows"],["render timechart","Draw a chart"]],"Common operators")]},
  {say:"Classic exam query: find machines that stopped sending heartbeats in the last fifteen minutes.",
   ops:[T("q2",440,60,[["Heartbeat"],["| summarize LastSeen = max(TimeGenerated) by Computer"],["| where LastSeen < ago(15m)"]],"Offline machines")]},
  {say:"Know the common tables: Heartbeat, Perf, Event for Windows, Syslog for Linux, and AzureActivity for the activity log.",
   ops:[T("tb",440,230,[["Table","Contains"],["Heartbeat","Agent check-ins"],["Perf","Performance counters"],["Event","Windows event logs"],["Syslog","Linux logs"],["AzureActivity","Activity log"]],"Common tables")]}
 ],
 takeaways:["Queries flow: Table | operator | operator.","where filters; project picks columns; summarize aggregates by groups.","ago(1h), bin(TimeGenerated, 5m), render timechart.","Tables: Heartbeat, Perf, Event, Syslog, AzureActivity, AzureDiagnostics."],
 traps:["summarize count() by Computer returns one row per computer, not the raw events.","String comparison with == is case-sensitive; =~ is case-insensitive."],
 mnemonic:"Where filters, Summarize squashes, Project picks, Render paints.",
 lab:"In a workspace with a VM connected, run Heartbeat | summarize count() by bin(TimeGenerated, 5m) | render timechart, then change it to show only the last 30 minutes.",
 ref:"https://learn.microsoft.com/en-us/kusto/query/tutorials/learn-common-operators"};

LESSONS.alerts={id:"alerts",title:"Alerts & action groups",mins:3,
 keywords:["alert","alert rule","action group","alert processing rule","severity","metric alert","log alert","activity log alert","webhook","logic app","runbook","maintenance window","suppress alerts"],
 scenes:[
  {say:"An alert rule watches a signal and fires when a condition is met. It has a scope, a condition, actions, and details like severity.",
   ops:[B("vm","vm",60,220,"vm-web1"),B("ar","policy",360,220,"Alert rule","CPU > 85% for 5 min",230),B("ag","users",700,220,"Action group","ag-ops",200),L("a","vm","ar","signal","dash"),L("b","ar","ag","fires","ok")]},
  {say:"Signals can be metrics, log search results, activity log events, or resource and service health.",
   ops:[T("sg",60,330,[["Signal","Example"],["Metric","CPU > 85% for 5 minutes"],["Log search","More than 10 errors in AppTraces in 15 min"],["Activity log","Someone deletes a VM"],["Service/Resource health","Azure outage affecting you"]],"Signal types")]},
  {say:"An action group is a reusable list of who to notify and what to run: email, SMS, push or voice, plus webhooks, Logic Apps, Functions or Automation runbooks.",
   ops:[...D("sg"),T("ac",560,320,[["Action group: ag-ops",""],["Notify","Email, SMS, push, voice"],["Run","Webhook, Logic App, Function, runbook, ITSM"]]),P(["ar","ag"],"Sev 1","bad")]},
  {say:"Severity runs from zero, critical, to four, verbose. Metric alerts are stateful, so they resolve on their own when the condition clears.",
   ops:[N("n1",60,330,"Severity: Sev0 Critical … Sev4 Verbose\nMetric alerts resolve automatically","accent")]},
  {say:"Planned maintenance tonight? An alert processing rule can suppress notifications for a time window, across many alert rules at once.",
   ops:[...D("n1"),B("pr","lock",360,60,"Alert processing rule","Sat 22:00–02:00 · suppress",260),L("c","pr","ar","applies to","dash"),P(["ar","ag"],"","bad",true)]},
  {say:"Processing rules can also add an action group to every alert in a scope, so you don't edit dozens of rules one by one.",
   ops:[N("n2",60,330,"Alert processing rules: suppress in a window\nor add action groups at scale","ok")]}
 ],
 takeaways:["Alert rule = scope + condition (signal) + action groups + severity.","Signals: metric, log search, activity log, resource/service health.","Action groups are reusable: notifications plus automation (webhook, Logic App, Function, runbook, ITSM).","Severity Sev0 (critical) to Sev4 (verbose).","Alert processing rules suppress notifications during maintenance or add action groups at scale."],
 traps:["To silence alerts during a maintenance window, don't disable rules. Use an alert processing rule.","\"Notify when someone deletes a resource group\" is an activity log alert, not a metric alert."],
 mnemonic:"Rule watches, Group acts, Processing rule hushes.",
 lab:"Create an action group that emails you, then a metric alert on a VM for CPU > 80% using it. Add an alert processing rule that suppresses it for the next hour.",
 ref:"https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview"};

LESSONS.insights={id:"insights",title:"Insights & the Azure Monitor agent",mins:2,
 keywords:["vm insights","storage insights","network insights","azure monitor agent","ama","data collection rule","dcr","dependency agent","map","workbook","guest metrics"],
 scenes:[
  {say:"Insights are ready-made monitoring views for a resource type: VM insights, Storage insights, Network insights and more.",
   ops:[T("in",60,60,[["Insight","Shows"],["VM insights","Performance charts, process and connection map"],["Storage insights","Capacity, availability, latency, transactions"],["Network insights","Topology, health, connectivity"],["Container insights","AKS and container workloads"]],"Azure Monitor Insights")]},
  {say:"To see inside a VM, like memory or disk use by the guest OS, install the Azure Monitor agent. It replaced the legacy Log Analytics agent.",
   ops:[C(),B("vm","vm",60,220,"vm-web1","Azure Monitor agent",220),B("dcr","policy",420,220,"Data collection rule","what + where",220),B("law","app",760,220,"Workspace","",170),
        L("a","vm","dcr","","dash"),L("b","dcr","law","","ok"),P(["vm","dcr","law"],"Perf, Event","signal")]},
  {say:"A data collection rule tells the agent what to collect, like counters and event logs, and where to send it. One rule can apply to many machines.",
   ops:[N("n1",60,330,"DCR = what to collect + where to send\nAssociate one DCR with many VMs","accent")]},
  {say:"VM insights adds performance charts, and with the Dependency agent, a map of processes and connections between machines.",
   ops:[...D("n1"),N("n2",60,330,"VM insights Map → needs Dependency agent","accent")]},
  {say:"Storage insights needs no setup. It shows capacity, availability and latency across all your storage accounts in one workbook.",
   ops:[...D("n2"),N("n3",60,330,"Storage insights: built from platform metrics,\nno agent needed","ok")]}
 ],
 takeaways:["Insights: curated views (VM, Storage, Network, Containers) built on workbooks.","Guest OS data needs the Azure Monitor agent plus a data collection rule.","The legacy Log Analytics agent (MMA) is retired; use the Azure Monitor agent.","VM insights Map needs the Dependency agent.","Storage and Network insights use platform data, no agent."],
 traps:["\"Monitor memory usage inside the VM\" needs the agent; Memory isn't a host platform metric for most VMs.","Network insights and Network Watcher work together: insights show health, Watcher tools diagnose."],
 mnemonic:"Agent collects, DCR directs, Insights display.",
 lab:"Enable VM insights on a VM, wait 15 minutes, open the Performance and Map tabs, and find the data collection rule it created.",
 ref:"https://learn.microsoft.com/en-us/azure/azure-monitor/vm/vminsights-overview"};

LESSONS.vaults={id:"vaults",title:"Recovery Services & Backup vaults",mins:2,
 keywords:["recovery services vault","backup vault","azure backup","vault redundancy","cross region restore","soft delete backup","immutable vault","mars agent","workloads"],
 scenes:[
  {say:"Azure Backup stores recovery points in a vault. There are two vault types, and each protects different workloads.",
   ops:[B("rsv","vnet",40,60,"Recovery Services vault","",420,420),B("bv","vnet",500,60,"Backup vault","",420,420),
        B("a1","vm",80,120,"Azure VMs","",200),B("a2","sql",80,200,"SQL / SAP HANA in VMs","",240),B("a3","storage",80,280,"Azure Files","",200),B("a4","onprem",80,360,"On-premises (MARS)","",230),
        B("b1","storage",540,120,"Azure Disks","",200),B("b2","storage",540,200,"Azure Blobs","",200),B("b3","sql",540,280,"Azure Database for PostgreSQL","",300),B("b4","cube",540,360,"AKS","",200)]},
  {say:"For VM backups, the vault must be in the same region as the VMs it protects.",
   ops:[N("n1",500,440,"Vault region = VM region (for VM backup)","bad")]},
  {say:"Set the vault's storage redundancy, LRS, ZRS or GRS, before you protect the first item. With GRS you can enable Cross Region Restore.",
   ops:[C(),B("v","vnet",40,60,"rsv-prod","Central India · GRS",420,300),B("rp","storage",100,160,"Recovery points","",200),B("sec","mg",560,60,"South India","paired region",360,300),B("rp2","storage",640,160,"Copy","Cross Region Restore",200),
        P(["rp","rp2"],"geo","signal"),N("n2",40,400,"Redundancy: set before first backup · GRS + Cross Region Restore","accent")]},
  {say:"Soft delete keeps deleted backup data for fourteen days by default, so an attacker or a mistake can't wipe your backups instantly.",
   ops:[...D("n2"),N("n3",40,400,"Soft delete: 14 days by default · immutable vaults block changes","ok")]},
  {say:"For on-premises Windows files and folders, install the MARS agent and back up straight to a Recovery Services vault.",
   ops:[...D("n3"),N("n4",40,400,"On-premises files/folders → MARS agent → Recovery Services vault","accent")]}
 ],
 takeaways:["Recovery Services vault: Azure VMs, SQL/SAP HANA in VMs, Azure Files, on-premises (MARS/MABS).","Backup vault: Azure Disks, Blobs, PostgreSQL, AKS.","VM backup needs a vault in the same region as the VM.","Set vault redundancy before the first backup; GRS enables Cross Region Restore.","Soft delete keeps deleted backup data 14 days by default."],
 traps:["You can't change vault redundancy after items are protected.","Backing up a VM in West Europe to a vault in Central India isn't allowed."],
 mnemonic:"Recovery Services = Classic workloads. Backup vault = newer data services.",
 lab:"Create a Recovery Services vault in the same region as a test VM, set redundancy to LRS, and enable backup with the default policy. Trigger Backup now.",
 ref:"https://learn.microsoft.com/en-us/azure/backup/backup-azure-recovery-services-vault-overview"};

LESSONS.bpolicy={id:"bpolicy",title:"VM backup policies",mins:2,
 keywords:["backup policy","standard policy","enhanced policy","instant restore","snapshot retention","retention","daily","weekly","monthly","yearly","app-consistent","crash-consistent"],
 scenes:[
  {say:"A backup policy sets when backups run and how long recovery points are kept.",
   ops:[T("pol",60,60,[["Policy: daily-prod",""],["Schedule","Daily at 23:00 IST"],["Instant restore snapshots","2 days"],["Daily points","Keep 30 days"],["Weekly (Sunday)","Keep 12 weeks"],["Monthly (1st)","Keep 12 months"],["Yearly (Jan 1)","Keep 7 years"]],"Backup policy")]},
  {say:"Each backup first takes a snapshot on the VM's disks for instant restore, then transfers the data to the vault.",
   ops:[B("vm","vm",560,90,"vm-db1"),B("sn","storage",560,200,"Snapshot","instant restore tier",210),B("vt","vnet",540,320,"Vault","",260,150),B("rp","storage",580,380,"Recovery point","vault tier",190),
        P(["vm","sn"],"1","signal"),P(["sn","rp"],"2","signal")]},
  {say:"Standard policies back up once a day. Enhanced policies allow several backups a day and are required for Trusted Launch VMs.",
   ops:[C(),T("cmp",60,60,[["","Standard","Enhanced"],["Frequency","Once a day","Up to every 4 hours"],["Snapshot retention","1–5 days","1–30 days"],["Trusted Launch VMs","Not supported","Supported"]],"Policy types")]},
  {say:"Backups are app-consistent when the VM is running: VSS on Windows, scripts on Linux. A stopped VM gets crash-consistent backups.",
   ops:[N("n1",60,260,"Running: app-consistent (VSS / pre-post scripts)\nStopped: crash-consistent","accent")]},
  {say:"Exam pattern: more than one backup a day, or a Trusted Launch VM, means an enhanced policy.",
   ops:[N("n2",60,340,"Multiple backups/day or Trusted Launch → Enhanced","ok")]}
 ],
 takeaways:["Policy = schedule + retention (daily, weekly, monthly, yearly).","Backups snapshot first (instant restore), then transfer to the vault.","Standard: once a day, 1–5 days snapshots. Enhanced: up to every 4 hours, 1–30 days, Trusted Launch.","Running VMs get app-consistent backups; stopped VMs get crash-consistent ones."],
 traps:["A standard policy can't take more than one backup per day.","Changing a VM's policy applies the new retention to future points; existing points follow their policy rules."],
 mnemonic:"Snapshot first, vault second; Enhanced for many a day.",
 lab:"Create an enhanced policy with backups every 4 hours and assign it to a test VM. Check Backup jobs after the first run.",
 ref:"https://learn.microsoft.com/en-us/azure/backup/backup-azure-vms-introduction"};

LESSONS.restore={id:"restore",title:"Restoring VMs and files",mins:2,
 keywords:["restore","restore vm","restore disks","replace existing","file recovery","item level restore","cross region restore","alternate location","recovery point"],
 scenes:[
  {say:"When something breaks, pick a recovery point and a restore type.",
   ops:[T("rt",60,60,[["Restore type","Result"],["Create new virtual machine","A new VM from the recovery point"],["Restore disks","Disks + template; you build the VM"],["Replace existing","Swap the existing VM's disks"],["File recovery","Mount the point, copy individual files"],["Cross Region Restore","Restore in the paired region (GRS)"]],"Restore options")]},
  {say:"Restore disks is the flexible choice. You get the disks and a template, so you can change the size, network or settings before creating the VM.",
   ops:[R("rt",2,"accent")]},
  {say:"Need one deleted file? Use file recovery. A script mounts the recovery point as a drive, you copy the file, then unmount.",
   ops:[R("rt",4,"ok"),B("rp","storage",560,300,"Recovery point","Tue 23:00",190),B("pc","vm",560,420,"Admin PC","mounted as F:",190),P(["rp","pc"],"iSCSI mount","signal")]},
  {say:"Run the file recovery script on a machine with a compatible operating system, and unmount when you're done.",
   ops:[N("n1",60,300,"File recovery script: compatible OS\nunmount when finished","accent")]},
  {say:"If the whole region is down and the vault is GRS with Cross Region Restore enabled, restore in the secondary region.",
   ops:[R("rt",5,"accent"),...D("n1"),N("n2",60,300,"Region down? GRS vault + Cross Region Restore","ok")]}
 ],
 takeaways:["Restore types: Create new VM, Restore disks, Replace existing, File recovery, Cross Region Restore.","Restore disks lets you customize before creating the VM.","File recovery mounts a recovery point to copy individual files.","Cross Region Restore needs a GRS vault with the feature enabled."],
 traps:["Restoring a whole VM to recover one file is slow and unnecessary. Use file recovery.","Replace existing needs the VM to exist; it restores disks over it."],
 mnemonic:"Whole VM, Disks only, Replace, or just a File.",
 lab:"From a VM backup, use File Recovery to download the script, mount the recovery point on another VM, copy one file, and unmount.",
 ref:"https://learn.microsoft.com/en-us/azure/backup/backup-azure-arm-restore-vms"};

LESSONS.asr={id:"asr",title:"Azure Site Recovery",mins:3,
 keywords:["site recovery","asr","disaster recovery","replication","failover","test failover","failback","reprotect","recovery plan","rpo","rto","commit"],
 scenes:[
  {say:"Azure Site Recovery keeps a running copy of your VMs in another region, so the whole app can fail over if the primary region goes down.",
   ops:[B("p","mg",30,60,"Central India","primary",420,330),B("s","mg",510,60,"South India","recovery region",420,330),B("v1","vm",90,140,"vm-web1"),B("v2","sql",90,240,"vm-db1"),
        B("r1","vm",570,140,"vm-web1","replica"),B("r2","sql",570,240,"vm-db1","replica"),B("rsv","vnet",760,180,"Vault","",150,120),P(["v1","r1"],"replicate","signal"),P(["v2","r2"],"replicate","signal")]},
  {say:"The Recovery Services vault lives in the target region, not the source region. Replication is continuous.",
   ops:[N("n1",30,410,"Vault: in the TARGET region · continuous replication","accent")]},
  {say:"A recovery plan groups VMs and sets the order: database first, then web servers, with scripts or runbooks in between.",
   ops:[...D("n1"),T("plan",30,410,[["Recovery plan: shop-dr",""],["Group 1","vm-db1  →  runbook: update DNS"],["Group 2","vm-web1, vm-web2"]])]},
  {say:"Test failover brings up replicas in an isolated network. Production keeps running, and nothing is affected. Do it regularly.",
   ops:[...D("plan"),N("n2",30,410,"Test failover: isolated VNet, zero production impact","ok")]},
  {say:"In a real disaster, fail over, then commit. When the primary region is back, reprotect, and fail back.",
   ops:[...D("n2"),T("st",30,410,[["Failover","Commit","Reprotect","Failback"]])]},
  {say:"Backup or Site Recovery? Backup restores data to a point in time. Site Recovery keeps the app running somewhere else.",
   ops:[C(),T("cmp",80,100,[["","Azure Backup","Azure Site Recovery"],["Goal","Recover data","Keep the app running elsewhere"],["Typical RPO","Hours (daily backups)","Seconds to minutes"],["Restores","Points in time, files","Whole VMs in another region"],["Use for","Deletion, corruption, ransomware","Regional outage"]],"Backup vs Site Recovery")]}
 ],
 takeaways:["Site Recovery replicates VMs continuously to another region (or on-premises to Azure).","The vault for Azure-to-Azure replication is in the target region.","Recovery plans order failover groups and run scripts or runbooks.","Test failover uses an isolated network with no production impact.","Sequence: failover → commit → reprotect → failback."],
 traps:["Creating the vault in the same region as the source VMs fails for Azure-to-Azure replication.","Site Recovery isn't a backup. Corrupted data replicates too; use Azure Backup for point-in-time recovery."],
 mnemonic:"Test it, Fail it, Commit it, Reprotect it, Bring it back.",
 lab:"Enable replication for a small VM to another region, wait for it to be protected, then run a test failover into an isolated VNet and clean it up.",
 ref:"https://learn.microsoft.com/en-us/azure/site-recovery/azure-to-azure-tutorial-enable-replication"};

LESSONS.breports={id:"breports",title:"Backup monitoring & reports",mins:2,
 keywords:["backup reports","backup alerts","backup jobs","business continuity center","backup center","azure monitor alerts backup","diagnostic settings vault"],
 scenes:[
  {say:"Check backup health in the vault's Backup jobs, or across all vaults in Business Continuity Center.",
   ops:[T("jb",60,60,[["Item","Operation","Status"],["vm-web1","Backup","Completed"],["vm-db1","Backup","Failed"],["share: finance","Backup","Completed"]],"Backup jobs"),R("jb",2,"bad")]},
  {say:"Built-in Azure Monitor alerts fire for failed backup and restore jobs. Route them to an action group to get email or a Teams message.",
   ops:[B("al","policy",560,60,"Backup alert","Job failed · vm-db1",230),B("ag","users",560,180,"Action group","ag-backup-ops",230),L("a","al","ag","notify","ok"),P(["al","ag"],"","bad")]},
  {say:"For trends, like storage used or jobs over months, use Backup reports. They need the vault's diagnostic settings sending data to a Log Analytics workspace.",
   ops:[B("v","vnet",60,280,"rsv-prod","",260,150),B("ds","policy",340,340,"Diagnostic setting","",200),B("law","app",600,340,"Workspace","Backup reports",200),L("b","ds","law","","ok"),P(["ds","law"],"","signal")]},
  {say:"Exam pattern: email me when a backup fails, alerts with an action group. Show backup usage over six months, Backup reports with a workspace.",
   ops:[N("n1",60,460,"Failure notice → alert + action group · Long-term trends → Backup reports","ok")]}
 ],
 takeaways:["Backup jobs show per-vault job status; Business Continuity Center gives a cross-vault view.","Azure Monitor alerts for backup failures route through action groups.","Backup reports need vault diagnostic settings sending to a Log Analytics workspace."],
 traps:["Backup reports stay empty until diagnostic settings are configured on each vault.","Classic backup alerts are being replaced by Azure Monitor alerts. Use action groups."],
 mnemonic:"Jobs for today, Alerts for failures, Reports for trends.",
 lab:"Add a diagnostic setting on a Recovery Services vault to a Log Analytics workspace, then open Backup reports a day later and review the Usage tab.",
 ref:"https://learn.microsoft.com/en-us/azure/backup/configure-reports"};

/* ----- Monitoring questions ----- */
Object.assign(CASES,{adatum:{title:"A. Datum Logistics",text:"A. Datum runs a shipment-tracking app on VMs in Central India.\n\n• The ops team must receive an SMS and email when average CPU on any app VM stays above 85% for 10 minutes.\n• No alert notifications should be sent during the monthly Saturday maintenance window.\n• Security wants to search Key Vault access events with KQL for one year.\n• VMs must be backed up every 4 hours. Some are Trusted Launch VMs.\n• If Central India becomes unavailable, the app must run in South India within an hour, with the database VM starting before the web VMs.\n• Managers want a monthly view of backup storage usage across all vaults."}});
SERIES.s5="Note: This question is part of a series that presents the same scenario. Each question has a different solution. Determine whether the solution meets the goal. After you answer a question in this series, you can't return to it.";

